void fuzzRoundtripMeshletV(const uint8_t* data, size_t size)
{
	size_t vertex_count = size / 4;
	if (vertex_count > 256)
		vertex_count = 256;

	unsigned char tri[4] = {0, 1, 2};

	unsigned char buf[4096];
